div.script:

(function () {
    function tdbSha256(ascii) {
        function rightRotate(value, amount) { return (value >>> amount) | (value << (32 - amount)); }
        var mathPow = Math.pow, maxWord = mathPow(2, 32), lengthProperty = 'length', i, j, result = '', words = [];
        var asciiBitLength = ascii[lengthProperty] * 8;
        var hash = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
        var k = [
            0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
            0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
            0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
            0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
            0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
            0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
            0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
            0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
        ];
        words = [];
        for (i = 0; i < ascii[lengthProperty]; i++) {
            words[i >> 2] |= (ascii.charCodeAt(i) & 0xff) << (24 - (i % 4) * 8);
        }
        words[asciiBitLength >> 5] |= 0x80 << (24 - (asciiBitLength % 32));
        words[(((asciiBitLength + 64) >> 9) << 4) + 15] = asciiBitLength;
        for (i = 0; i < words[lengthProperty]; i += 16) {
            var w = words.slice(i, i + 16);
            for (var idx = 0; idx < 16; idx++) {
                if (typeof w[idx] === 'undefined') w[idx] = 0;
            }
            var oldHash = hash.slice(0);
            for (j = 0; j < 64; j++) {
                if (j >= 16) {
                    var s0 = rightRotate(w[j - 15], 7) ^ rightRotate(w[j - 15], 18) ^ (w[j - 15] >>> 3);
                    var s1 = rightRotate(w[j - 2], 17) ^ rightRotate(w[j - 2], 19) ^ (w[j - 2] >>> 10);
                    w[j] = (w[j - 16] + s0 + w[j - 7] + s1) | 0;
                }
                var s1 = rightRotate(oldHash[4], 6) ^ rightRotate(oldHash[4], 11) ^ rightRotate(oldHash[4], 25);
                var ch = (oldHash[4] & oldHash[5]) ^ (~oldHash[4] & oldHash[6]);
                var temp1 = (oldHash[7] + s1 + ch + k[j] + w[j]) | 0;
                var s0 = rightRotate(oldHash[0], 2) ^ rightRotate(oldHash[0], 13) ^ rightRotate(oldHash[0], 22);
                var maj = (oldHash[0] & oldHash[1]) ^ (oldHash[0] & oldHash[2]) ^ (oldHash[1] & oldHash[2]);
                var temp2 = (s0 + maj) | 0;
                oldHash = [(temp1 + temp2) | 0, oldHash[0], oldHash[1], oldHash[2], (oldHash[3] + temp1) | 0, oldHash[4], oldHash[5], oldHash[6]];
            }
            for (j = 0; j < 8; j++) { hash[j] = (hash[j] + oldHash[j]) | 0; }
        }
        for (i = 0; i < 8; i++) {
            for (j = 3; j >= 0; j--) {
                var b = (hash[i] >> (8 * j)) & 255;
                result += (b < 16 ? '0' : '') + b.toString(16);
            }
        }
        return result;
    }


    function tdbEncrypt(plain) {
        if (!plain) return plain;
        var hash = tdbSha256(plain);
        var utf8 = unescape(encodeURIComponent(plain));
        var cipher = '';
        for (var i = 0; i < utf8.length; i++) {
            var code = utf8.charCodeAt(i) ^ 0x5A;
            var hex = code.toString(16);
            cipher += (hex.length < 2 ? '0' : '') + hex;
        }
        return 'SHA256:' + hash + ':' + cipher;
    }

    function secureSubmit(form) {
        try {
            sessionStorage.setItem('tdb_open_home_menu', 'true');
            var pInput = form.querySelector('input[type="password"]') || document.getElementById('password') || form.querySelector('input[name="password"]');
            if (!pInput || !pInput.value) return;

            var rawVal = pInput.value;
            // Nếu đã là chuỗi SHA256:<hash>:<cipher> thì không mã hóa lặp
            if (rawVal.indexOf('SHA256:') === 0 && rawVal.split(':').length >= 3) return;

            var payloadVal = tdbEncrypt(rawVal);

            // Tạo hoặc cập nhật hidden input để gửi qua mạng
            var hidden = form.querySelector('input#tdb_password_payload');
            if (!hidden) {
                hidden = document.createElement('input');
                hidden.type = 'hidden';
                hidden.id = 'tdb_password_payload';
                hidden.name = 'password';
                form.appendChild(hidden);
            }
            hidden.value = payloadVal;

            // Tạm thời bỏ thuộc tính name của ô password hiển thị để form không gửi plaintext
            // TUYỆT ĐỐI KHÔNG SỬA pInput.value để:
            // 1. Ô hiển thị vẫn giữ nguyên mật khẩu người dùng gõ
            // 2. Trình duyệt lưu đúng mật khẩu thật trong Password Manager
            // 3. Không bao giờ hiển thị chuỗi mã hóa trong ô nhập liệu
            pInput.removeAttribute('name');

            setTimeout(function () {
                pInput.setAttribute('name', 'password');
            }, 1200);
        } catch (err) {
            console.error('tdbSecureSubmit error:', err);
        }
    }

    window.tdbSha256 = tdbSha256;
    window.tdbEncrypt = tdbEncrypt;
    window.tdbSecureSubmit = secureSubmit;

    // Bắt chặn sự kiện submit ngay lập tức ở capturing phase trên toàn document
    document.addEventListener('submit', function (e) {
        var target = e.target;
        if (target && target.tagName === 'FORM') {
            secureSubmit(target);
        }
    }, true);
})();
